import{_ as s,o as t,c as o,a2 as r}from"./chunks/framework.CQxpk36T.js";const h=JSON.parse('{"title":"Votre propriété","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1793563901000}'),a={name:"guide/index.md"};function i(d,e,n,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="votre-propriete" tabindex="-1">Votre propriété <a class="header-anchor" href="#votre-propriete" aria-label="Permalink to &quot;Votre propriété&quot;">​</a></h1><p>Une propriété est un <strong>dossier</strong> : <code>proprietes/&lt;nom&gt;/</code>. HAven ne connaît aucune maison en particulier ; il lit le dossier choisi et en tire toute la maquette. Ce guide part de la maison d&#39;exemple et vous mène jusqu&#39;à la vôtre.</p><h2 id="creer-son-dossier" tabindex="-1">Créer son dossier <a class="header-anchor" href="#creer-son-dossier" aria-label="Permalink to &quot;Créer son dossier&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proprietes/exemple</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proprietes/ma-maison</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;PROPRIETE=ma-maison&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span></code></pre></div><p>Relancez <code>npm run dev</code> : c&#39;est désormais <code>proprietes/ma-maison/</code> qui s&#39;affiche, encore identique à l&#39;exemple. Sans <code>.env.local</code>, HAven affiche <code>proprietes/exemple</code>.</p><h2 id="ce-que-contient-le-dossier" tabindex="-1">Ce que contient le dossier <a class="header-anchor" href="#ce-que-contient-le-dossier" aria-label="Permalink to &quot;Ce que contient le dossier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fichier</th><th>Rôle</th><th>Page</th></tr></thead><tbody><tr><td><code>index.ts</code></td><td>Assemble le paquet (à ne pas modifier)</td><td></td></tr><tr><td><code>terrain.json</code> ou <code>cadastre.json</code></td><td>La source du terrain</td><td><a href="/HAven-docs/guide/terrain">Le terrain</a></td></tr><tr><td><code>site.json</code></td><td>Le terrain calculé : contour, emprises des bâtiments, routes, position GPS</td><td><a href="/HAven-docs/reference/terrain">Référence</a></td></tr><tr><td><code>propriete.ts</code></td><td>Les bâtiments, leurs toits, portes, fenêtres, pièces, et les abords</td><td><a href="/HAven-docs/guide/batiments">Bâtiments</a></td></tr><tr><td><code>plans.ts</code></td><td>Plans intérieurs pour la vue en coupe (facultatif : <code>export const plans = {}</code>)</td><td><a href="/HAven-docs/guide/plans">Plans intérieurs</a></td></tr><tr><td><code>retouches.json</code></td><td>Créé par l&#39;éditeur de la page, appliqué par-dessus le reste</td><td><a href="/HAven-docs/guide/editeur">L&#39;éditeur</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Vos données restent chez vous</p><p><code>.gitignore</code> exclut tous les dossiers de <code>proprietes/</code> sauf l&#39;exemple, ainsi que <code>.env.local</code>. Votre adresse, vos plans et vos coordonnées ne partent jamais avec le code. Pour les sauvegarder, gardez-les dans un dépôt privé à part, ou sauvegardez ce dossier comme le reste de vos fichiers.</p></div><h2 id="le-repere" tabindex="-1">Le repère <a class="header-anchor" href="#le-repere" aria-label="Permalink to &quot;Le repère&quot;">​</a></h2><p>Le même partout, dans tous les fichiers :</p><ul><li>des <strong>mètres</strong> ;</li><li><code>x</code> vers l&#39;<strong>est</strong>, <code>z</code> vers le <strong>sud</strong>, <code>y</code> vers le haut ;</li><li>l&#39;origine au <strong>centre de la propriété</strong>.</li></ul><p>Un point au sol s&#39;écrit <code>[x, z]</code> : <code>[9, 7]</code> est à 9 m à l&#39;est et 7 m au sud du centre.</p><h2 id="cote-cour-cote-dos" tabindex="-1">Côté cour, côté dos <a class="header-anchor" href="#cote-cour-cote-dos" aria-label="Permalink to &quot;Côté cour, côté dos&quot;">​</a></h2><p>Chaque bâtiment a deux longs pans et deux pignons. Le <strong>côté cour</strong> est le long pan qui regarde le point <code>courtyard</code> de <code>propriete.ts</code> ; l&#39;autre est le <strong>côté dos</strong>. Les extrémités sont les <strong>pignons</strong>, « début » (x local négatif) et « fin ».</p><p>Placez <code>courtyard</code> là où vous êtes quand vous regardez vos façades principales : au bout de l&#39;allée, au milieu de la cour.</p><h2 id="le-chemin-conseille" tabindex="-1">Le chemin conseillé <a class="header-anchor" href="#le-chemin-conseille" aria-label="Permalink to &quot;Le chemin conseillé&quot;">​</a></h2><ol><li><strong><a href="/HAven-docs/guide/terrain">Le terrain</a></strong> : le contour et les emprises des bâtiments, depuis le cadastre ou à la main.</li><li><strong><a href="/HAven-docs/guide/editeur">L&#39;éditeur de la page</a></strong> : ajuster les volumes au doigt, sans code.</li><li><strong><a href="/HAven-docs/guide/batiments">Bâtiments et toits</a></strong> : les types, les toits, les noues.</li><li><strong><a href="/HAven-docs/guide/facades">Façades, portes, fenêtres</a></strong> : ce qui perce les murs et ce qui s&#39;y accroche.</li><li><strong><a href="/HAven-docs/guide/pieces">Pièces et Zones</a></strong> : le lien avec Home Assistant.</li><li><strong><a href="/HAven-docs/guide/abords">Les abords</a></strong> : voitures, cour, portail, poules, arbres, haies, panneaux solaires.</li><li><strong><a href="/HAven-docs/guide/plans">Plans intérieurs</a></strong> : la vue en coupe, si vous avez vos plans.</li></ol><div class="tip custom-block"><p class="custom-block-title">Vérifier ses fichiers</p><p><code>npm test</code> vérifie la cohérence de chaque dossier de <code>proprietes/</code> : identifiants des sections, voitures et places, pièces des plans… Lancez-le après une grosse modification.</p></div>`,18)])])}const g=s(a,[["render",i]]);export{h as __pageData,g as default};
